const STATUS: Record<string, string> = { open: '인수 대기', acknowledged: '인수 완료', investigating: '조사 중', action_pending: '적용 대기', contained: '억제 확인', recovering: '복구 관찰', resolved: '복구 완료', false_positive: '오탐 종결', duplicate: '중복 종결', accepted_risk: '위험 수용', preview: '승인 대기', approved: '승인 완료', queued: '작업 대기', applying: '적용 중', applied: '적용 확인', revoke_requested: '해제 요청', released: '해제 확인', release_failed: '해제 실패', expired: '유효기간 만료', failed: '실패', unknown: '결과 미확인', provider_accepted: '제공자 접수', not_configured: '채널 설정 필요', retrying: '재시도 대기', sending: '전송 중' };
const ROLE: Record<string, string> = { admin: '관리자', analyst: '분석가', responder: '대응자', approver: '승인자', viewer: '열람자' };
const CLOSED = ['resolved', 'false_positive', 'duplicate', 'accepted_risk'];
// 빈 값은 '—' 대신 이유가 보이게: 아직 없음(기록 전) / 아직 측정되지 않음 / 측정 안 됨. 호출부에서 문맥에 맞는 문구를 넘길 수 있다.
const date = (value: string | null, empty = '아직 없음') => value ? new Date(value).toLocaleString('ko-KR', { month: '2-digit', day: '2-digit', hour: '2-digit', minute: '2-digit', second: '2-digit' }) : empty;
const duration = (seconds: number | null, empty = '아직 측정되지 않음') => seconds === null ? empty : seconds < 60 ? `${seconds.toFixed(0)}초` : `${(seconds / 60).toFixed(1)}분`;
const pct = (value: number | null | undefined, empty = '측정 안 됨') => value == null ? empty : `${(value * 100).toFixed(1)}%`;
const LOADING = '불러오는 중';
// 상태별 "다음 할 일" 안내. 버튼·전이 로직은 그대로 두고 설명만 덧붙인다.
const NEXT_GUIDE: Record<string, string> = {
  open: '이 사건을 맡으면 확인 기한 타이머가 멈추고, 당신이 담당자로 기록됩니다.',
  acknowledged: '판단 근거를 적고 [조사 시작]을 누르면 조사 단계로 넘어가요. 차단이 필요하면 [대응 미리보기]에서 요청하세요.',
  investigating: '차단을 요청하려면 [대응 미리보기]로 가세요. 차단이 현장에 적용되고 유입이 줄어들면 [억제 효과 확인]을 누를 수 있어요.',
  action_pending: '다른 승인자가 승인하면 현장 방화벽에 기한부로 적용돼요. 적용이 확인되고 유입이 줄면 [억제 효과 확인]으로 기록하세요.',
  contained: '차단이 풀리고(자동 해제 또는 해제 요청) 정상 요청이 계속 성공하면 [복구 관찰 시작]을 누르세요.',
  recovering: '안정화 관찰 시간이 지나고 성공률이 유지되면 [정상 복구 확인]으로 사건을 종결해요.',
};
const TRANSITION_NOTICE: Record<string, string> = {
  investigating: '조사를 시작했어요. 근거를 모으고, 필요하면 [대응 미리보기]에서 차단을 요청하세요.',
  contained: '억제 효과를 기록했어요. 차단이 풀리고 정상 요청이 계속 성공하면 복구 관찰로 넘어가세요.',
  recovering: '복구 관찰을 시작했어요. 안정화 시간이 지나면 [정상 복구 확인]을 누를 수 있어요.',
  resolved: '정상 복구를 확인하고 사건을 종결했어요.',
  false_positive: '오탐으로 종결했어요. 근거는 타임라인에 남아요.',
  accepted_risk: '위험 수용으로 종결했어요. 근거는 타임라인에 남아요.',
  duplicate: '중복 사건으로 종결했어요.',
};
function download(value: unknown, filename: string) { const url = URL.createObjectURL(new Blob([JSON.stringify(value, null, 2)], { type: 'application/json' })); const a = document.createElement('a'); a.href = url; a.download = filename; a.click(); URL.revokeObjectURL(url); }
function Badge({ value }: { value: string }) { const code = PRIORITY[value] || MODEL_STAGE[value]; return <span className={`ops-badge ops-state-${value}`} title={code ? termTitle(code) : undefined}><i />{STATUS[value] || (code ? withOriginal(code) : value)}</span>; }
function Empty({ title, text }: { title: string; text: string }) { return <div className="ops-empty"><ShieldCheck size={30}/><h3>{title}</h3><p>{text}</p></div>; }
function Failure({ message, retry }: { message: string; retry?: () => void }) { return message ? <div className="ops-error" role="alert"><CircleAlert size={17}/><span>{message}</span>{retry && <button onClick={retry}>다시 시도</button>}</div> : null; }
function useResource<T>(path: string, params: Record<string, unknown>, revision: number, interval = 5000) {
  const [data, setData] = useState<T | null>(null), [error, setError] = useState('');
  const signature = JSON.stringify(params);
  useEffect(() => { const controller = new AbortController(); let running = false;
    const load = async () => { if (running) return; running = true; try { const value = await opsGet<T>(path, JSON.parse(signature), controller.signal); if (!controller.signal.aborted) { setData(value); setError(''); } } catch (e) { if (!controller.signal.aborted) setError(errorMessage(e)); } finally { running = false; } };
    setData(null); void load(); const timer = window.setInterval(load, interval); return () => { controller.abort(); clearInterval(timer); };
  }, [path, signature, revision, interval]);
  return { data, error };
}

function SignIn({ onLogin }: { onLogin: (operator: Operator) => void }) {
  const [username, setUsername] = useState(''), [password, setPassword] = useState(''), [error, setError] = useState(''), [busy, setBusy] = useState(false);
  return <section className="ops-signin"><div className="ops-signin-story"><span className="ops-eyebrow">사건 대응 워크스페이스</span><h1>탐지에서<br/>확인된 복구까지.</h1><p>하나의 사건에서 근거를 확인하고,<br/>담당자를 연결하고, 대응의 결과를 증명하세요.</p><div className="ops-signin-steps">관측 <ChevronRight size={14}/> 인수 <ChevronRight size={14}/> 대응 <ChevronRight size={14}/> 복구</div><ShieldCheck size={110} strokeWidth={.8}/></div>
    <form onSubmit={async e => { e.preventDefault(); setBusy(true); setError(''); try { onLogin(await operatorLogin(username, password)); } catch (e) { setError(errorMessage(e)); } finally { setPassword(''); setBusy(false); } }}><div className="ops-lock"><LockKeyhole size={24}/></div><h2>운영자 로그인</h2><p>개인 계정으로 판단과 대응 이력을 남깁니다.</p><Failure message={error}/><label>사용자 이름<input autoComplete="username" value={username} onChange={e => setUsername(e.target.value)} required/></label><label>비밀번호<input type="password" autoComplete="current-password" value={password} onChange={e => setPassword(e.target.value)} required/></label><button className="ops-primary" disabled={busy}>{busy ? '확인 중…' : '워크스페이스 열기'}<ArrowRight size={16}/></button><small>관리자가 발급한 개인 계정이 필요합니다.<br/>공개 네트워크에서는 HTTPS로 접속하세요.</small></form></section>;
}

export function OperationsWorkspace({ hash }: { hash: string }) {
  const [actor, setActor] = useState<Operator | null>(null), [checking, setChecking] = useState(true);
  const [source, setSource] = useState('live'), [revision, setRevision] = useState(0), [error, setError] = useState(''), [busy, setBusy] = useState(false), [notice, setNotice] = useState('');
  const refresh = useCallback(() => setRevision(v => v + 1), []);
  useEffect(() => { const expire = () => { setActor(null); setNotice(''); setError(''); }; window.addEventListener('ops-session-expired', expire); return () => window.removeEventListener('ops-session-expired', expire); }, []);
  // 행동 결과 피드백(스낵바)은 8초 뒤 스스로 사라진다. 닫기 버튼으로 바로 지울 수도 있다.
  useEffect(() => { if (!notice) return; const timer = setTimeout(() => setNotice(''), 8000); return () => clearTimeout(timer); }, [notice]);
  useEffect(() => { let alive = true; operatorSession().then(r => { if (alive) setActor(r); }).catch(() => {}).finally(() => { if (alive) setChecking(false); }); return () => { alive = false; }; }, []);
  const section = hash.split('?')[0];
  const selected = new URLSearchParams(hash.split('?')[1] || '').get('id');
  const perform = async (operation: () => Promise<unknown>, success: string) => { setBusy(true); setError(''); try { await operation(); setNotice(success); refresh(); } catch (e) { setError(errorMessage(e)); } finally { setBusy(false); } };
  const rehearse = async (scenario: string) => {
    const run = await opsPost<{ id: string }>('/rehearsals', { scenario_id: scenario });
    setSource('simulation');
    for (let attempt = 0; attempt < 12; attempt++) {
      const result = await opsGet<{ items: Incident[] }>('/incidents', { source: 'simulation', scenario_run_id: run.id });
      if (result.items.length) { location.hash = `#incidents?id=${result.items[0].id}`; return; }
      await new Promise(resolve => setTimeout(resolve, 1000));
    }
    throw new Error('훈련은 시작됐지만 사건 생성 확인이 지연되고 있습니다. 받은편지함에서 확인하세요.');
  };
  if (checking) return <div className="ops-loading" role="status">운영자 세션 확인 중…</div>;
  if (!actor) return <SignIn onLogin={setActor}/>;
  const title = ({ '#incidents': '사건 대응', '#operations': '대응 관제', '#actions': '대응 관리', '#notifications': '알림 센터', '#assets': '자산과 대응 지점', '#models': '모델 운영' } as Record<string, string>)[section] || '사건 대응';
  return <div className="ops-workspace"><div className="ops-page-head"><div><span className="ops-eyebrow">탐지 → 확인된 복구</span><h1>{title}</h1><p>근거를 확인하고, 다음 행동을 결정하세요.</p></div><div className="ops-account"><div className="ops-avatar">{actor.name.slice(0, 1)}</div><span><b>{actor.name}</b><small>{ROLE[actor.role]}</small></span><button aria-label="운영자 로그아웃" onClick={() => void perform(async () => { await operatorLogout(); setActor(null); }, '')}><LogOut size={16}/></button></div></div>
    <div className="ops-toolbar"><nav aria-label="대응 워크스페이스"><a className={section === '#operations' ? 'active' : ''} href="#operations">관제</a><a className={section === '#incidents' ? 'active' : ''} href="#incidents">사건</a><a className={section === '#actions' ? 'active' : ''} href="#actions">대응</a><a className={section === '#notifications' ? 'active' : ''} href="#notifications">알림</a><a className={section === '#models' ? 'active' : ''} href="#models">모델</a><a className={section === '#assets' ? 'active' : ''} href="#assets">자산</a></nav><div className="ops-tools"><label className="ops-source-label">데이터 출처<select aria-label="관제 데이터 출처" value={source} onChange={e => { setSource(e.target.value); if (selected) location.hash = '#incidents'; }}><option value="live">LIVE · 실제 관측</option><option value="simulation">SIMULATION · 훈련</option></select></label><button aria-label="운영 데이터 새로고침" onClick={refresh}><RefreshCw size={16}/></button></div></div>
    {source === 'simulation' && <div className="ops-training"><FlaskConical size={18}/><span><b>격리된 모의 훈련</b> · 외부 알림과 실제 네트워크 변경 없이 승인·적용·복구 흐름을 검증합니다.</span></div>}
    <Failure message={error}/>{notice && <div className="ops-notice" role="status"><CheckCircle2 size={16}/>{notice}<button aria-label="알림 닫기" onClick={() => setNotice('')}><X size={14}/></button></div>}
    {actor.is_test_account && <div className="ops-warning" role="status"><FlaskConical size={17}/>공개 테스트 계정 · 실제 네트워크 대응과 외부 알림은 비활성화되어 있습니다.</div>}
    {section === '#operations' ? <Overview source={source} revision={revision}/> : section === '#notifications' ? <Notifications source={source} revision={revision} perform={perform} busy={busy}/> : section === '#actions' ? <Actions source={source} revision={revision} actor={actor} perform={perform} busy={busy}/> : section === '#assets' ? <Assets revision={revision} actor={actor} perform={perform} busy={busy}/> : section === '#models' ? <Models revision={revision} actor={actor} perform={perform} busy={busy}/> : selected ? <IncidentView key={selected} id={selected} onSource={setSource} revision={revision} actor={actor} perform={perform} busy={busy}/> : <Inbox source={source} revision={revision} actor={actor} onRehearse={scenario => void perform(() => rehearse(scenario), scenario === 'shared_source' ? '공유 출발지 훈련 사건을 열었어요. 차단 안전 점검(Gate)이 왜 자동 차단을 거부했는지 확인해 보세요.' : '새 훈련 사건을 열었어요. 먼저 [확인하고 맡기]로 담당자가 되어 보세요.')} busy={busy}/>}
  </div>;
}
type Perform = (operation: () => Promise<unknown>, success: string) => Promise<void>;

function Overview({ source, revision }: { source: string; revision: number }) {
  const { data: stats, error } = useResource<Outcomes>('/metrics', { source }, revision);
  return <><Failure message={error}/><div className="ops-hero"><div><span className="ops-eyebrow">대응 현황</span><h2>지금, 확인이 필요한 사건.</h2><p>최근 7일 · {source === 'live' ? '실제 운영 지표' : '훈련 성과'}</p></div><a className="ops-primary" href="#incidents">사건 받은편지함<ArrowRight size={16}/></a></div><MetricCards stats={stats}/><div className="ops-outcomes">{[['담당자 인수 시간', 'MTTA', stats?.mtta], ['억제 확인까지', 'MTTC', stats?.mttc], ['정상 복구까지', 'MTTR', stats?.mttr]].map(([label, code, timing]) => { const t = timing as Outcomes['mtta'] | undefined; return <section className="ops-card" key={String(code)}><span>{String(code)}</span><h3>{String(label)}</h3><strong>{duration(t?.mean_seconds ?? null)}</strong><p>{t?.samples ? `완료된 ${t.samples}개 사건의 평균 · 가장 느린 5% 기준(p95) ${duration(t.p95_seconds ?? null)}` : '완료된 사건이 쌓이면 평균이 계산돼요'}</p></section>; })}</div><div className="ops-footnote"><CircleAlert size={16}/>MTTD는 독립적으로 기록된 공격 시작 시각이 있어야 산출합니다. 미측정 값은 0으로 표시하지 않습니다. 운영과 훈련 통계는 합산하지 않습니다.</div></>;
}
function MetricCards({ stats }: { stats: Outcomes | null }) { return <div className="ops-metric-grid">{[
  ['미인수 중요 사건', stats?.unacknowledged_urgent, '1·2순위(P1·P2)', Shield], ['확인 기한 초과', stats?.overdue, '담당자 확인 필요', Clock3], ['실행 중 대응', stats?.active_actions, '해제 확인까지 추적', Activity], ['전달·복구 실패', stats ? stats.notification_failures + stats.recovery_failures : undefined, '결과 미확인 포함', Bell],
].map(([label, value, hint, Icon], i) => { const Symbol = Icon as typeof Shield; return <section className={`ops-metric ops-metric-${i}`} key={String(label)}><span>{String(label)}<Symbol size={16}/></span><strong>{value == null ? <span className="ops-empty-value">{stats ? '측정 안 됨' : LOADING}</span> : String(value)}{value != null && <small>건</small>}</strong><p>{String(hint)}</p></section>; })}</div>; }

function Inbox({ source, revision, actor, onRehearse, busy }: { source: string; revision: number; actor: Operator; onRehearse: (scenario: string) => void; busy: boolean }) {
  const [status, setStatus] = useState('active'), [owner, setOwner] = useState(''), [priority, setPriority] = useState(''), [draft, setDraft] = useState(''), [q, setQ] = useState(''), [page, setPage] = useState(1);
  const { data, error } = useResource<{ items: Incident[]; total: number }>('/incidents', { source, status, owner, priority, q, page }, revision);
  const { data: stats } = useResource<Outcomes>('/metrics', { source }, revision);
  useEffect(() => setPage(1), [source, status, owner, priority, q]);
  return <><MetricCards stats={stats}/><div className="ops-inbox"><aside className="ops-saved"><span className="ops-eyebrow">빠른 보기</span><button className={!owner ? 'active' : ''} onClick={() => setOwner('')}><Layers3 size={16}/>모든 사건</button><button className={owner === 'mine' ? 'active' : ''} onClick={() => setOwner('mine')}><Users size={16}/>내가 맡은 사건</button><button className={owner === 'unassigned' ? 'active' : ''} onClick={() => setOwner('unassigned')}><Clock3 size={16}/>미배정 사건</button><div className="ops-practice"><FlaskConical size={22}/><h3>대응 흐름을 연습하세요</h3><p>탐지부터 담당자 인수, 별도 승인과 복구 확인까지.</p><button disabled={busy || actor.role === 'viewer'} onClick={() => onRehearse('syn_flood')}>대응 훈련 시작<ArrowRight size={14}/></button><button className="ops-text-button" disabled={busy || actor.role === 'viewer'} onClick={() => onRehearse('shared_source')}><Bot size={13}/>공유 출발지 훈련 · 게이트 거부 확인</button></div></aside><section className="ops-card ops-inbox-main"><div className="ops-section-head"><div><h2>사건 받은편지함 <small>{data?.total ?? '집계 중'}</small></h2><p>우선순위와 확인 기한 순으로 정렬됩니다.</p></div><span className="ops-live-dot">5초마다 갱신</span></div><div className="ops-filter-row"><form onSubmit={e => { e.preventDefault(); setQ(draft.trim()); }}><Search size={16}/><input aria-label="사건 검색" placeholder="사건 또는 대상 IP 검색" value={draft} onChange={e => setDraft(e.target.value)}/><button type="submit">검색</button></form><select aria-label="사건 우선순위" value={priority} onChange={e => setPriority(e.target.value)}><option value="">모든 우선순위</option>{['P1', 'P2', 'P3', 'P4'].map(p => <option key={p} value={p}>{withOriginal(PRIORITY[p])}</option>)}</select><select aria-label="사건 상태" value={status} onChange={e => setStatus(e.target.value)}><option value="active">진행 중</option><option value="all">모든 상태</option>{['open', 'acknowledged', 'investigating', 'recovering', 'resolved', 'false_positive'].map(s => <option key={s} value={s}>{STATUS[s]}</option>)}</select></div><Failure message={error}/>{!data && !error ? <div className="ops-loading">사건을 불러오고 있습니다…</div> : data?.items.length ? <div className="ops-incident-list">{data.items.map(r => <a href={`#incidents?id=${r.id}`} key={r.id} className="ops-incident-row"><div className="ops-row-mark"><Badge value={r.priority}/></div><div className="ops-row-content"><div><h3>{humanizeCodes(r.title)}</h3><Badge value={r.status}/></div><p>{r.asset_name}<span>·</span>{r.event_count.toLocaleString()}개 관측<span>·</span>{r.summary.schema_version === 2 ? '상세 관측(v2)' : '기본 관측(v1)'}</p><div className="ops-row-meta"><span><Users size={12}/>{r.owner_name || '담당자 미배정'}</span><span><Clock3 size={12}/>{r.acknowledged_at ? `최근 관측 ${date(r.last_seen_at)}` : `확인 기한 ${date(r.ack_due_at)}`}</span></div></div><ChevronRight size={19}/></a>)}</div> : <Empty title={source === 'live' ? '조건에 맞는 사건이 없습니다' : '아직 훈련 사건이 없습니다'} text={source === 'live' ? '새로운 탐지 이벤트가 수신되면 관련 관측을 하나의 사건으로 묶습니다.' : '대응 훈련을 실행하면 모의 사건이 이곳에 표시됩니다.'}/>}<div className="ops-pagination"><span>{data?.total ?? 0}개 사건 · {page}페이지</span><button disabled={page === 1} onClick={() => setPage(p => p - 1)}>이전</button><button disabled={page * 30 >= (data?.total ?? 0)} onClick={() => setPage(p => p + 1)}>다음</button></div></section></div></>;
}

function IncidentView({ id, revision, actor, perform, busy, onSource }: { id: string; revision: number; actor: Operator; perform: Perform; busy: boolean; onSource: (source: string) => void }) {
  const { data: incident, error } = useResource<IncidentDetail>(`/incidents/${id}`, {}, revision);
  const { data: context } = useResource<ResponseContext>(`/incidents/${id}/response-context`, {}, revision);
  const { data: operators } = useResource<{ items: Operator[] }>('/operators', {}, revision, 30000);
  useEffect(() => { if (incident) onSource(incident.source); }, [incident?.source, onSource]);
  const [tab, setTab] = useState('overview'), [note, setNote] = useState(''), [reason, setReason] = useState(''), [assignee, setAssignee] = useState('');
  if (!incident) return <><a className="ops-back" href="#incidents"><ArrowLeft size={15}/>받은편지함</a><Failure message={error}/><div className="ops-loading">사건 근거를 불러오고 있습니다…</div></>;
  const transition = (status: string) => perform(() => opsPost(`/incidents/${id}/transition`, { version: incident.version, status, reason }), TRANSITION_NOTICE[status] ?? '상태를 바꾸고 근거를 기록했어요.');
  const next = ({ acknowledged: ['investigating', '조사 시작'], action_pending: ['contained', '억제 효과 확인'], investigating: incident.actions.length ? ['contained', '억제 효과 확인'] : null, contained: ['recovering', '복구 관찰 시작'], recovering: ['resolved', '정상 복구 확인'] } as Record<string, string[] | null>)[incident.status];
  const canInvestigate = actor.role !== 'viewer';
  const observations = [...(context?.observations || [])].reverse();
  const latestRun = incident.actions[0];
  const target = next?.[0];
  let nextBlocked = '';
  if (target && ['contained', 'recovering', 'resolved'].includes(target)) {
    const since = target === 'contained' ? latestRun?.applied_at : target === 'recovering' ? latestRun?.released_at : incident.recovering_at;
    const relevant = observations.filter(o => o.point_id === latestRun?.point_id && since && Date.parse(o.observed_at) >= Date.parse(since));
    if (!latestRun || !since) nextBlocked = '아직 누를 수 없어요 · 현장 방화벽 프로그램(agent)이 적용·해제를 보고하기를 기다리는 중이에요.';
    else if (target !== 'contained' && latestRun.status !== 'released') nextBlocked = '아직 누를 수 없어요 · 차단이 실제로 풀렸다는 확인(해제 확인)이 먼저 필요해요.';
    else if (relevant.length < 2 || relevant.some(o => !o.healthy || o.success_rate < .99)) nextBlocked = '아직 누를 수 없어요 · 정상 요청 성공률 99% 이상이 두 번 연속 관측되어야 해요.';
    else if (target === 'contained' && relevant[relevant.length - 1].ingress_pps > incident.summary.peak_pps * .5) nextBlocked = '아직 누를 수 없어요 · 유입량이 최대치의 절반 아래로 줄어든 것이 확인되어야 해요.';
    else if (target === 'resolved' && (Date.now() - Date.parse(since)) / 1000 < (context?.recovery_observation_seconds || 60)) nextBlocked = `아직 누를 수 없어요 · 안정화 관찰 중이라 ${context?.recovery_observation_seconds || 60}초가 지나야 확인할 수 있어요.`;
  }
  return <><a className="ops-back" href="#incidents"><ArrowLeft size={15}/>사건 받은편지함</a><Failure message={error}/><section className="ops-case-header"><div className="ops-case-top"><div className="ops-chips"><Badge value={incident.priority}/><Badge value={incident.status}/><span className={`ops-source ${incident.source}`}>{incident.source === 'simulation' ? 'SIMULATION · 모의 훈련' : 'LIVE · 실제 관측'}</span><code>INC-{id.slice(0, 8)}</code></div><button className="ops-secondary" onClick={() => void perform(async () => download(await opsGet(`/incidents/${id}/report`), `incident-${id}.json`), '사건 보고서를 내려받았어요.')}><ArrowDownToLine size={15}/>보고서</button></div><h2>{humanizeCodes(incident.title)}</h2><div className="ops-case-meta"><span><Shield size={14}/>{incident.asset_name}</span><span><Users size={14}/>{incident.owner_name || '담당자 미배정'}</span><span><Clock3 size={14}/>최초 {date(incident.created_at)}</span><span>{incident.event_count}개 연결 이벤트</span></div><div className="ops-progress">{[['open', '탐지'], ['acknowledged', '담당자 인수'], ['investigating', '조사'], ['contained', '억제 확인'], ['recovering', '복구 관찰'], ['resolved', '종결']].map(([state, label], index) => { const order = ['open', 'acknowledged', 'investigating', 'action_pending', 'contained', 'recovering', 'resolved']; const complete = !CLOSED.includes(incident.status) || incident.status === 'resolved'; const reached = complete && order.indexOf(incident.status) >= order.indexOf(state); return <div className={reached ? 'reached' : ''} key={state}><span>{reached ? <Check size={12}/> : index + 1}</span>{label}</div>; })}</div></section>
    <div className="ops-case-layout"><div className="ops-case-main"><div className="ops-tabs" role="tablist" aria-label="사건 상세 탭">{[['overview', '개요'], ['evidence', '증거'], ['response', '대응'], ['timeline', '타임라인']].map(([value, label]) => <button role="tab" aria-selected={tab === value} aria-controls={`ops-tab-${value}`} key={value} onClick={() => setTab(value)}>{label}</button>)}</div><div id={`ops-tab-${tab}`} role="tabpanel">
    {tab === 'overview' && <><section className="ops-card"><div className="ops-section-head"><div><h3>판단에 필요한 근거</h3><p>관측값과 해석을 구분합니다.</p></div><ShieldCheck size={20}/></div><div className="ops-facts"><div><span>탐지 방식</span><b>{incident.summary.evidence === 'rules' ? '규칙만 사용' : incident.summary.evidence === 'validated_model' ? '검증된 AI 모델' : '규칙 + 검증된 AI 모델'}</b></div><div><span className="term" title={termTitle(UNIT.pps)}>최대 초당 패킷(pps)</span><b>{incident.summary.peak_pps.toLocaleString()} pps</b></div><div><span>관측 출발지</span><b>{incident.summary.sources.length}개</b></div><div><span className="term" title="수집기가 보내는 관측 항목(feature)의 버전. v2는 목적지·양방향 정보까지 포함합니다">관측 항목 버전</span><b>{incident.summary.schema_version === 2 ? 'v2 · 상세 관측' : 'v1 · 기본 관측(일부 항목 없음)'}</b></div></div>{!incident.asset_id && <div className="ops-warning"><CircleAlert size={16}/>등록되지 않은 자산이에요. [자산] 메뉴에서 서비스와 차단 적용 위치(point)를 등록해야 대응을 실행할 수 있어요.</div>}{incident.summary.automatic && <AutomaticDecisionCard decision={incident.summary.automatic}/>}{incident.summary.automatic?.gate && <GateCard gate={incident.summary.automatic.gate}/>}<div className="ops-explanation">{incident.attack_type === 'SYN_FLOOD' ? '서비스로 집중된 SYN 유입이 설정된 임계값을 넘었습니다. 정상 요청 상태와 실제 관측 위치를 함께 확인하세요.' : incident.summary.evidence === 'validated_model' ? '승격된 모델이 이상 관측을 감지했습니다. 점수는 공격 확률이나 별도의 독립 증거가 아닙니다.' : '이상 트래픽 규칙에 해당하는 관측이 반복되었습니다. 승인된 스캔·백업·배포 작업인지 먼저 확인하세요.'}</div></section><ServiceChart observations={observations}/></>}
    {tab === 'evidence' && <section className="ops-card"><div className="ops-section-head"><div><h3>연결된 원본 이벤트</h3><p>최근 최대 100개 · {incident.events_truncated ? '일부 표시' : '전체 표시'}</p></div></div><div className="ops-table-scroll"><table><thead><tr><th>관측 시각</th><th>출발지</th><th>목적지</th><th className="term" title={termTitle(UNIT.pps)}>초당 패킷(pps)</th><th className="term" title={termTitle(UNIT.synRatio)}>접속 요청 비율(SYN)</th></tr></thead><tbody>{incident.events.map(e => <tr key={e.event_id}><td>{date(e.detected_at)}</td><td><code>{e.flow.src_ip}</code></td><td><code>{e.flow.dst_ip}:{e.flow.dst_port}</code></td><td>{e.features.pkt_rate.toLocaleString()}</td><td>{pct(e.features.syn_ratio)}</td></tr>)}</tbody></table></div></section>}
    {tab === 'response' && <><ResponsePanel incident={incident} context={context} actor={actor} perform={perform} busy={busy}/><ServiceChart observations={observations}/><RunCards runs={incident.actions} actor={actor} perform={perform} busy={busy}/></>}
    {tab === 'timeline' && <section className="ops-card"><div className="ops-section-head"><div><h3>사건 타임라인</h3><p>판단·인수·승인·실행·복구의 저장된 이력</p></div></div><div className="ops-timeline">{incident.timeline.map(entry => <article key={entry.id}><span className="ops-timeline-dot"/><time>{date(entry.created_at)}</time><div><h4>{timelineLabel(entry.kind)}</h4><p>{entry.actor_name}</p>{entry.detail.reason != null && <blockquote>{String(entry.detail.reason)}</blockquote>}{entry.detail.text != null && <blockquote>{String(entry.detail.text)}</blockquote>}<details><summary>기록 상세</summary><pre>{JSON.stringify(entry.detail, null, 2)}</pre></details></div></article>)}</div></section>}
    </div><section className="ops-card ops-note-form"><h3>조사 메모</h3><textarea aria-label="사건 조사 메모" placeholder="판단 근거와 다음 담당자에게 전달할 내용을 남기세요." value={note} onChange={e => setNote(e.target.value)} maxLength={2000}/><button className="ops-secondary" disabled={!note.trim() || busy || !canInvestigate} onClick={() => void perform(async () => { await opsPost(`/incidents/${id}/notes`, { reason: note }); setNote(''); }, '조사 메모를 저장했어요.')}>메모 기록</button></section></div>
    <aside className="ops-case-side"><section className="ops-card ops-next"><span className="ops-eyebrow">다음 할 일</span><h3>{incident.status === 'open' ? '이 사건을 맡아주세요' : CLOSED.includes(incident.status) ? '사건이 종결되었습니다' : '근거를 확인하고 진행하세요'}</h3><p className="ops-guide">{NEXT_GUIDE[incident.status] ?? (CLOSED.includes(incident.status) ? '기록은 [타임라인] 탭과 [보고서]에서 볼 수 있어요.' : '정책 적용과 억제 성공은 별개예요. 서비스 관측으로 효과를 확인해요.')}</p>{incident.status === 'open' ? <button className="ops-primary" disabled={busy || !canInvestigate} onClick={() => void perform(() => opsPost(`/incidents/${id}/ack`, { version: incident.version }), '이 사건을 맡았어요. 확인 기한이 멈추고 담당자로 기록됐어요.')}><Users size={16}/>확인하고 맡기</button> : !CLOSED.includes(incident.status) && <><label>판단 근거 <small className="ops-label-hint">3자 이상 · 버튼을 누르면 타임라인에 함께 저장돼요</small><textarea aria-label="상태 변경 근거" value={reason} onChange={e => setReason(e.target.value)} placeholder="관측과 판단 근거를 기록하세요" maxLength={2000}/></label>{nextBlocked && <small role="status">{nextBlocked}</small>}{next && <button className="ops-primary" disabled={busy || reason.trim().length < 3 || !canInvestigate || !!nextBlocked} onClick={() => void transition(next[0])}>{next[1]}<ArrowRight size={15}/></button>}{['acknowledged', 'investigating'].includes(incident.status) && <button className="ops-secondary" onClick={() => setTab('response')}>대응 미리보기<Shield size={15}/></button>}{['action_pending', 'contained', 'recovering'].includes(incident.status) && <button className="ops-secondary" disabled={busy || reason.trim().length < 3 || !canInvestigate} onClick={() => void transition('investigating')}>다시 조사하기</button>}{['acknowledged', 'investigating'].includes(incident.status) && <details><summary>다른 종결 사유</summary>{[['false_positive', '오탐으로 종결'], ['accepted_risk', '위험 수용으로 종결'], ['duplicate', '중복으로 종결']].map(([value, text]) => <button key={value} disabled={busy || reason.trim().length < 3 || !canInvestigate} onClick={() => void transition(value)}>{text}</button>)}</details>}</>}</section><section className="ops-card"><h3>담당자와 인계</h3><p>{incident.owner_name || '아직 담당자가 없습니다.'}</p>{incident.owner_id && !CLOSED.includes(incident.status) && (incident.owner_id === actor.id || actor.role === 'admin') && <><select aria-label="인계할 담당자" value={assignee} onChange={e => setAssignee(e.target.value)}><option value="">담당자 선택</option>{operators?.items.filter(o => o.role !== 'viewer' && o.id !== incident.owner_id).map(o => <option key={o.id} value={o.id}>{o.name} · {ROLE[o.role]}</option>)}</select><button className="ops-secondary" disabled={!assignee || reason.length < 3 || busy} onClick={() => void perform(() => opsPost(`/incidents/${id}/assign`, { version: incident.version, operator_id: assignee, reason }), '담당자를 인계하고 사유를 기록했어요.')}>근거와 함께 인계</button><small>위의 판단 근거를 인계 사유로 저장합니다.</small></>}</section><section className="ops-card"><h3>알림과 사람의 확인</h3>{incident.notifications.map(n => <div className="ops-delivery-mini" key={n.id}><span>{codeLabel(CHANNEL, n.channel)}</span><Badge value={n.status}/>{n.acknowledged_at && <small><Check size={12}/>담당자 인수 확인</small>}</div>)}<a href="#notifications">전달 기록 확인<ChevronRight size={13}/></a></section></aside></div></>;
}

function timelineLabel(kind: string) { return ({ 'incident.opened': '새 사건 생성', 'incident.acknowledged': '담당자 인수', 'incident.investigating': '조사 시작', 'incident.note': '조사 메모', 'incident.assigned': '담당자 인계', 'response.previewed': '대응 영향 미리보기', 'response.approved': '별도 승인자 승인', 'response.queued': '에이전트 적용 대기', 'response.applied': '에이전트 적용 확인', 'response.revoke_requested': '정책 해제 요청', 'response.released': '정책 해제 확인', 'incident.contained': '억제 효과 확인', 'incident.recovering': '복구 관찰 시작', 'incident.resolved': '정상 복구 확인', 'incident.escalated': '확인 기한 초과·상향 알림', 'notification.provider_accepted': '알림 제공자 접수', 'response.auto_approved': '게이트 저위험 · 승인 없이 자동 적용', 'response.auto_declined': '게이트 고위험 · 자동 차단 거부', 'response.auto_limit_reached': '자동 경로 시간당 상한 · 승인 경로로 전환', 'response.auto_gate_error': '게이트 오류 · 승인 경로로 폴백', 'response.auto_response': '자동 경로 스위치 변경', 'response.kill_switch': '전역 중지 변경', 'asset.auto_response': '자산 자동 경로 등록 변경', 'response.expired': '명령 유효기간 만료', 'response.failed': '에이전트 적용 거부' } as Record<string, string>)[kind] || kind; }
function ServiceChart({ observations }: { observations: ResponseContext['observations'] }) { return <section className="ops-card"><div className="ops-section-head"><div><h3>대응 전후 서비스 관측</h3><p>유입량 · 정상 요청 성공률 · {observations[0]?.source === 'simulation' ? '명시적 합성 관측' : '에이전트 측정'}</p></div><Activity size={20}/></div>{observations.length ? <div className="ops-service-charts"><div><span className="term" title={termTitle(UNIT.pps)}>관측 유입량 · 초당 패킷(pps)</span><ResponsiveContainer width="100%" height={155}><AreaChart data={observations}><CartesianGrid vertical={false} stroke="#edf1f6"/><XAxis dataKey="observed_at" tickFormatter={v => new Date(v).toLocaleTimeString('ko-KR', { minute: '2-digit', second: '2-digit' })} fontSize={10} minTickGap={55}/><YAxis width={38} fontSize={10}/><Tooltip/><Area type="monotone" dataKey="ingress_pps" name="초당 패킷(pps)" stroke="#5879db" fill="#ebf0fd" isAnimationActive={false}/></AreaChart></ResponsiveContainer></div><div><span>정상 요청 성공률</span><ResponsiveContainer width="100%" height={155}><LineChart data={observations}><CartesianGrid vertical={false} stroke="#edf1f6"/><XAxis dataKey="observed_at" tickFormatter={v => new Date(v).toLocaleTimeString('ko-KR', { minute: '2-digit', second: '2-digit' })} fontSize={10} minTickGap={55}/><YAxis domain={[0, 1]} tickFormatter={v => `${v * 100}%`} width={42} fontSize={10}/><Tooltip/><Line dataKey="success_rate" name="정상 요청 성공률" stroke="#169f8b" dot={false} isAnimationActive={false}/></LineChart></ResponsiveContainer></div></div> : <Empty title="서비스 관측 대기" text="등록된 에이전트의 측정이 있어야 대응 효과와 복구를 확인할 수 있습니다."/>}</section>; }

const HARD_STOP: Record<string, string> = { insufficient_evidence: '관측이 부족해 판단을 보류', protected_neighbourhood: '보호 대상 주소와 가까운 출발지', critical_asset_mixed_traffic: '중요 자산에 정상 트래픽이 섞여 있음' };
const DECISION: Record<string, string> = { applied: '자동으로 차단했어요 · 차단 안전 점검(Gate)이 저위험이라 승인 없이 적용', declined: '자동 차단을 하지 않았어요 · 점검 결과 고위험이라 승인자에게 넘김', limit_reached: '자동 차단을 멈췄어요 · 한 시간 상한에 도달해 승인 경로로 전환', gate_error: '점검 중 오류가 나서 안전하게 승인 경로로 넘겼어요' };
// 게이트 신호의 관측값은 숫자·문자열·객체({events: 1, seconds: 0} 등)가 섞여 온다. 객체는 "키 값" 나열로 보여준다.
function formatSignalValue(value: unknown): string {
  if (typeof value === 'number') return value.toLocaleString('ko-KR');
  if (value && typeof value === 'object') return Object.entries(value as Record<string, unknown>).map(([k, v]) => `${k} ${typeof v === 'number' ? v.toLocaleString('ko-KR') : String(v)}`).join(' · ');
  return String(value ?? '없음');
}
// 게이트 근거를 초보자 문장으로: 왜 자동 처리됐는지 / 왜 승인이 필요한지. 점수·임계·신호 값은 그대로 표시한다.
function gateWhy(gate: Gate) {
  const score = gate.score.toFixed(2), limit = gate.threshold.toFixed(2);
  if (gate.hard_stop) return `승인이 필요해요 · 점수와 상관없이 "${HARD_STOP[gate.hard_stop] || gate.hard_stop}" 조건에 걸려 자동 차단을 멈췄어요.`;
  return gate.level === 'high'
    ? `승인이 필요해요 · 실수로 정상 사용자까지 막을 위험 점수가 ${score}로 기준선 ${limit} 이상이라, 자동으로 차단하지 않고 다른 승인자가 검토해요.`
    : `자동 차단이 가능해요 · 위험 점수가 ${score}로 기준선 ${limit}보다 낮아, 자동 경로가 켜져 있으면 승인 없이 기한부로 차단해요.`;
}
function GateCard({ gate, compact }: { gate: Gate; compact?: boolean }) {
  const high = gate.level === 'high';
  const signals = Object.entries(gate.signals ?? {});
  return <div className={`ops-gate ${gate.level}`} role="group" aria-label="차단 안전 점검(Gate)"><header><Gauge size={18}/><b className="term" title={termTitle(OPS_TERM.gateScore)}>부수 피해 위험 {gate.score.toFixed(2)}</b><span className="ops-gate-level">{high ? '고위험 · 승인 경로' : '저위험 · 자동 경로 가능'}</span><small><span className="term" title={termTitle(OPS_TERM.gateThreshold)}>기준선 {gate.threshold.toFixed(2)}</span>{gate.hard_stop ? ` · 강제 정지: ${HARD_STOP[gate.hard_stop] || gate.hard_stop}` : ''}</small></header><div className="ops-gate-bar"><i style={{ width: `${Math.min(100, Math.round(gate.score * 100))}%` }}/></div><p className="ops-gate-why">{gateWhy(gate)}</p>{compact ? <p className="ops-muted">{gate.reasons[0]}</p> : <><ul>{gate.reasons.map(r => <li key={r}>{r}</li>)}</ul>{signals.length > 0 && <details><summary>점수를 만든 신호 {signals.length}개 보기</summary><div className="ops-gate-signals">{signals.map(([key, s]) => <div key={key} title={GATE_SIGNAL[key]?.description ?? key}><b>{GATE_SIGNAL[key] ? withOriginal(GATE_SIGNAL[key]) : key}</b>위험 {s.risk.toFixed(2)} × 가중치 {s.weight} · 관측값 {formatSignalValue(s.value)}</div>)}</div></details>}</>}</div>;
}
function AutomaticDecisionCard({ decision }: { decision: AutomaticDecision }) {
  return <div className={`ops-warning ops-auto-${decision.status}`}><Bot size={16}/><div><b>{DECISION[decision.status] || decision.status}</b> · 출발지 {decision.source_ip} · {date(decision.at)}{decision.blocked_by?.length ? <p>막힌 이유: {decision.blocked_by.join(' ')}</p> : null}</div></div>;
}
function AutomaticStatus({ context, source }: { context: ResponseContext | null; source: string }) {
  if (!context) return null;
  const a = context.automatic, gate = context.gates?.[source];
  return <><div className="ops-auto-line"><span title={termTitle(OPS_TERM.autoRoute)}><Bot size={14}/>자동 경로 <b>{a.switch ? '켜짐' : '꺼짐'}</b></span><span title="이 자산이 자동 경로에 등록되어 있는지">이 자산 <b>{a.asset_opt_in ? '등록됨' : '미등록'}</b></span><span className="term" title={termTitle(OPS_TERM.ttl)}>자동 해제 시간(TTL) <b>{a.ttl_seconds}초</b></span><span className="term" title={termTitle(OPS_TERM.gateThreshold)}>위험 기준선 <b>{a.threshold.toFixed(2)}</b></span></div>{a.decision && <AutomaticDecisionCard decision={a.decision}/>}{gate ? <GateCard gate={gate}/> : <p className="ops-muted">아직 없음 · 선택한 출발지에 대한 차단 안전 점검(Gate) 결과가 아직 계산되지 않았어요.</p>}</>;
}
function AutomaticControl({ data, actor, perform, busy }: { data: ActionsPage | null; actor: Operator; perform: Perform; busy: boolean }) {
  const [reason, setReason] = useState(''), [open, setOpen] = useState(false);
  return <section className="ops-card ops-control"><div><h2>자동 경로</h2><p>차단 안전 점검(Gate)이 저위험으로 판정한 출발지만 승인 없이 자동으로 차단해요. 그 밖은 모두 다른 승인자에게 넘어가고, 어느 경로든 정해진 시간이 지나면 커널이 스스로 차단을 풀어요(자동 해제 시간, TTL).</p><div className="ops-auto-line"><span><Bot size={14}/>상태 <b>{data ? (data.auto_response ? '켜짐' : '꺼짐') : LOADING}</b></span><span title="최근 1시간 동안 자동 차단을 쓴 횟수 / 상한">최근 1시간 <b>{data ? `${data.auto_usage.used} / ${data.auto_usage.limit}` : LOADING}</b></span><span className="term" title={termTitle(OPS_TERM.ttl)}>자동 해제 시간(TTL) <b>{data ? `${data.auto_ttl_seconds}초` : LOADING}</b></span><span className="term" title={termTitle(OPS_TERM.gateThreshold)}>위험 기준선 <b>{data ? data.risk_threshold.toFixed(2) : LOADING}</b></span></div></div>{actor.role === 'admin' && <button className="ops-secondary" onClick={() => setOpen(v => !v)}><Bot size={16}/>{data?.auto_response ? '자동 경로 끄기' : '자동 경로 켜기'}</button>}{open && <div className="ops-revoke"><input aria-label="자동 경로 변경 근거" placeholder="자동 경로 변경 근거" value={reason} onChange={e => setReason(e.target.value)}/><button className="ops-primary" disabled={busy || reason.length < 3} onClick={() => void perform(async () => { await opsPost('/auto-response', { enabled: !data?.auto_response, reason }); setOpen(false); }, '자동 경로 설정을 바꿨어요.')}>변경 확인</button></div>}</section>;
}

function ResponsePanel({ incident, context, actor, perform, busy }: { incident: IncidentDetail; context: ResponseContext | null; actor: Operator; perform: Perform; busy: boolean }) {
  const [point, setPoint] = useState(''), [source, setSource] = useState(incident.summary.sources[0] || ''), [ttl, setTtl] = useState(60), [action, setAction] = useState('block_source'), [reason, setReason] = useState(''), [rate, setRate] = useState(100);
  const canRequest = ['responder', 'admin'].includes(actor.role);
  return <section className="ops-card"><div className="ops-section-head"><div><h3>기한부 대응 미리보기</h3><p>차단할 대상과 자동 해제 시간을 정해 "미리보기"를 만들면, 본인이 아닌 다른 승인자가 검토한 뒤에만 실제로 적용돼요.</p></div><Shield size={20}/></div><AutomaticStatus context={context} source={source}/>{!context?.points.length ? <div className="ops-warning"><CircleAlert size={18}/>이 자산에는 차단을 적용할 위치(point)가 등록되어 있지 않아요. <a href="#assets">자산·대응 지점 확인</a></div> : <form className="ops-policy-form" onSubmit={e => { e.preventDefault(); void perform(() => opsPost(`/incidents/${incident.id}/action-previews`, { request_id: crypto.randomUUID(), version: incident.version, point_id: point || context.points[0].id, source_ip: source, ttl_seconds: ttl, action, rate_pps: rate, reason }), '대응 미리보기를 만들었어요. 이제 본인이 아닌 다른 승인자가 검토하면 실행돼요.'); }}><label><span className="term" title="차단 규칙이 실제로 적용될 현장 호스트">적용 지점</span><select aria-label="대응 적용 지점" value={point || context.points[0].id} onChange={e => setPoint(e.target.value)}>{context.points.map(p => <option key={p.id} value={p.id}>{p.name} · {codeLabel(POINT_MODE, p.mode)}</option>)}</select></label><label>관측 출발지<select aria-label="대응 출발지" value={source} onChange={e => setSource(e.target.value)}>{incident.summary.sources.map(ip => <option key={ip}>{ip}</option>)}</select></label><label>조치<select aria-label="대응 조치" value={action} onChange={e => setAction(e.target.value)}><option value="block_source">해당 서비스로의 임시 차단</option><option value="rate_limit">해당 서비스의 유입률 제한</option></select></label><label><span className="term" title={termTitle(OPS_TERM.ttl)}>자동 해제 시간(TTL)</span><select aria-label="대응 기한" value={ttl} onChange={e => setTtl(Number(e.target.value))}>{[30, 60, 120, 300].filter(n => n <= context.max_ttl_seconds).map(n => <option value={n} key={n}>{n}초 뒤 자동 해제</option>)}</select></label>{action === 'rate_limit' && <label><span className="term" title={termTitle(UNIT.pps)}>허용 초당 패킷(pps)</span><input type="number" min={10} max={100000} value={rate} onChange={e => setRate(Number(e.target.value))}/></label>}<label className="ops-full">요청 근거<textarea aria-label="대응 요청 근거" value={reason} onChange={e => setReason(e.target.value)} required minLength={3} maxLength={2000} placeholder="검토한 증거와 예상 서비스 영향을 적으세요"/></label><button className="ops-primary" disabled={busy || !canRequest || reason.trim().length < 3 || !['acknowledged', 'investigating'].includes(incident.status)}>대응 미리보기 생성<ArrowRight size={15}/></button>{!canRequest && <small>대응자 또는 관리자 역할이 필요합니다.</small>}{canRequest && !['acknowledged', 'investigating'].includes(incident.status) && <small>미리보기는 담당자 인수 후 조사 단계까지만 만들 수 있어요.</small>}</form>}<div className="ops-previews">{context?.previews.map(p => <PreviewCard key={p.id} preview={p} actor={actor} perform={perform} busy={busy}/>)}</div></section>;
}
function PreviewCard({ preview: p, actor, perform, busy }: { preview: ActionPreview; actor: Operator; perform: Perform; busy: boolean }) {
  const [reason, setReason] = useState(''), [checked, setChecked] = useState(false);
  const canApprove = ['approver', 'admin'].includes(actor.role) && p.requester_id !== actor.id && p.status === 'preview' && new Date(p.expires_at).getTime() > Date.now();
  return <article className="ops-preview"><div><Badge value={p.status}/>{p.origin === 'automatic' && <span className="ops-auto-badge"><Bot size={13}/>자동 적용 · 승인 불필요</span>}<span>{p.preview.mode === 'lab' ? '모의 실행 · 실제 네트워크는 바뀌지 않아요' : '실제 네트워크 변경'}</span></div><h4>{p.policy.source_ip} → {p.policy.destination_ip}:{p.policy.destination_port}</h4><p>{p.policy.action === 'block_source' ? '이 출발지의 서비스 접근을 막아요' : `이 출발지를 초당 ${p.policy.rate_pps.toLocaleString()}개 패킷(pps)까지만 허용해요`} · <span className="term" title={termTitle(OPS_TERM.ttl)}>{p.policy.ttl_seconds}초 뒤 자동 해제(TTL)</span></p><dl><div><dt><span className="term" title="차단 규칙이 실제로 적용될 현장 호스트">적용 지점</span></dt><dd>{p.preview.point}</dd></div><div><dt>정상 세션 영향</dt><dd>{p.preview.affected_sessions ?? '측정 안 됨'}</dd></div><div><dt><span className="term" title="이 시각이 지나면 미리보기가 만료되어 새로 만들어야 해요">승인 유효기간</span></dt><dd>{date(p.expires_at)}</dd></div><div><dt>요청 근거</dt><dd>{p.reason}</dd></div></dl><div className="ops-warning">{p.preview.impact}</div>{p.preview.gate && <GateCard gate={p.preview.gate} compact/>}{canApprove ? <div className="ops-approval"><label className="ops-checkbox"><input type="checkbox" checked={checked} onChange={e => setChecked(e.target.checked)}/>대상·보호 주소·기한과 정상 서비스 영향을 검토했습니다.</label><input aria-label="승인 근거" value={reason} onChange={e => setReason(e.target.value)} placeholder="승인 판단 근거" maxLength={2000}/><button className="ops-primary" disabled={!checked || reason.trim().length < 3 || busy} onClick={() => void perform(() => opsPost(`/action-requests/${p.id}/approve`, { policy_hash: p.policy_hash, reason }), '승인했어요. 현장 방화벽 프로그램(agent)이 적용을 보고하면 "적용 확인"으로 바뀌어요.')}>대응 승인 및 실행<ShieldCheck size={16}/></button><small className="ops-guide">누르면 현장 방화벽(nftables)에 기한부 차단이 적용돼요. 정해진 시간이 지나면 커널이 스스로 풀어요.</small></div> : p.status === 'preview' && <p className="ops-muted">{p.requester_id === actor.id ? '본인이 요청한 대응은 다른 승인자가 검토해야 합니다. (요청자와 승인자를 분리하는 2인 승인 규칙)' : '승인자 권한과 유효한 미리보기가 필요합니다.'}</p>}</article>;
}
function RunCards({ runs, actor, perform, busy }: { runs: ActionRun[]; actor: Operator; perform: Perform; busy: boolean }) {
  const [reason, setReason] = useState('');
  return <div className="ops-run-list">{runs.map(r => <article className="ops-card ops-run" key={r.id}><div className="ops-section-head"><div><h3>{r.policy.action === 'block_source' ? '기한부 접근 제한' : '기한부 유입률 제한'}</h3><p>{r.policy.source_ip} → {r.policy.destination_ip}:{r.policy.destination_port}</p></div><div className="ops-chips">{r.origin === 'automatic' && <span className="ops-auto-badge"><Bot size={13}/>자동 적용</span>}<Badge value={r.status}/></div></div><div className="ops-run-times"><span>적용 확인 <b>{date(r.applied_at, '아직 없음 · 현장 보고 대기')}</b></span><span className="term" title={termTitle(OPS_TERM.ttl)}>자동 해제 예정(TTL) <b>{date(r.expires_at, '적용 후 계산')}</b></span><span>해제 확인 <b>{date(r.released_at, '아직 없음')}</b></span></div>{r.last_error && <Failure message={r.last_error}/>}<p className="ops-muted">{r.agent_result.detail || '현장 방화벽 프로그램(agent)의 실행 보고를 기다리는 중'} · <a href={`#incidents?id=${r.incident_id}`}>연결된 사건 보기</a></p>{!['released', 'failed', 'expired'].includes(r.status) && ['responder', 'admin'].includes(actor.role) && <div className="ops-revoke"><input aria-label={`해제 근거 ${r.id}`} placeholder="해제 근거" value={reason} onChange={e => setReason(e.target.value)} maxLength={2000}/><button className="ops-danger" disabled={busy || reason.trim().length < 3} onClick={() => void perform(() => opsPost(`/actions/${r.id}/revoke`, { reason }), '해제 요청을 보냈어요. 현장에서 실제로 풀린 것이 확인되면 "해제 확인"으로 바뀌어요.')}><ShieldOff size={15}/>즉시 해제 요청</button><small className="ops-guide">자동 해제 시간을 기다리지 않고 지금 차단을 풀어 달라고 현장에 요청해요.</small></div>}</article>)}</div>;
}
function Actions({ source, revision, actor, perform, busy }: { source: string; revision: number; actor: Operator; perform: Perform; busy: boolean }) {
  const { data, error } = useResource<ActionsPage>('/actions', { source }, revision);
  const [reason, setReason] = useState(''), [expanded, setExpanded] = useState(false);
  return <><Failure message={error}/><section className="ops-card ops-control"><div><h2>승인과 실행을 한곳에서</h2><p><span className="term" title={termTitle(OPS_TERM.killSwitch)}>모든 대응 멈춤(Kill switch)</span>을 켜면 진행 중인 모든 차단의 해제를 요청하고 새 승인·자동 차단을 막아요. 현장에서 실제로 풀렸다고 보고하기 전에는 "해제 확인"으로 표시하지 않아요.</p></div>{actor.role === 'admin' && <button className="ops-danger" onClick={() => setExpanded(v => !v)}><ShieldOff size={16}/>{data?.kill_switch ? '전역 중지 해제' : '전체 대응 중지'}</button>}{expanded && <div className="ops-revoke"><input aria-label="전체 대응 중지 근거" placeholder="전역 제어 변경 근거" value={reason} onChange={e => setReason(e.target.value)}/><button className="ops-danger" disabled={busy || reason.length < 3} onClick={() => void perform(() => opsPost('/kill-switch', { enabled: !data?.kill_switch, reason }), '모든 대응 멈춤(Kill switch) 설정을 바꿨어요.')}>변경 확인</button></div>}</section>{data?.kill_switch && <div className="ops-warning"><ShieldOff size={17}/>모든 대응 멈춤(Kill switch)이 켜져 있어요 · 새 승인과 자동 차단이 모두 막혀 있어요.</div>}<AutomaticControl data={data} actor={actor} perform={perform} busy={busy}/><h2 className="ops-block-title">승인 대기 <small>{data?.pending.length || 0}</small></h2><div className="ops-preview-grid">{data?.pending.map(p => <PreviewCard key={p.id} preview={p} actor={actor} perform={perform} busy={busy}/>)}</div><h2 className="ops-block-title">실행과 해제 기록</h2>{data?.items.length ? <RunCards runs={data.items} actor={actor} perform={perform} busy={busy}/> : <Empty title="실행된 대응이 없습니다" text="사건 상세에서 대응 미리보기를 만들고 별도 승인자의 검토를 받으세요."/>}</>;
}
function Notifications({ source, revision, perform, busy }: { source: string; revision: number; perform: Perform; busy: boolean }) {
  const [status, setStatus] = useState(''), [retryId, setRetryId] = useState(''), [reason, setReason] = useState('');
  const { data, error } = useResource<{ items: Delivery[]; external_enabled: boolean }>('/notifications', { source, status }, revision);
  return <><Failure message={error}/><div className="ops-channel-banner"><Bell size={22}/><div><h3>전달과 확인은 서로 다른 단계입니다</h3><p>제공자 접수는 담당자 인수를 의미하지 않습니다. {data?.external_enabled ? '외부 채널 발송이 활성화되어 있습니다.' : '외부 발송 설정 대기 · 워크스페이스 알림은 기록됩니다.'}</p></div></div><section className="ops-card"><div className="ops-section-head"><h2>채널별 전달 이력</h2><select aria-label="알림 상태" value={status} onChange={e => setStatus(e.target.value)}><option value="">모든 상태</option>{['provider_accepted', 'failed', 'unknown', 'retrying', 'not_configured'].map(s => <option value={s} key={s}>{STATUS[s]}</option>)}</select></div>{data?.items.length ? <div className="ops-notification-list">{data.items.map(n => <article key={n.id}><div className="ops-channel-icon"><Bell size={18}/></div><div className="ops-notification-body"><a href={`#incidents?id=${n.incident_id}`}><h3>{humanizeCodes(n.payload.title)}</h3></a><p>{codeLabel(CHANNEL, n.channel)} · {n.destination || '수신 대상 미설정'} · 시도 {n.attempts}회</p><small>{date(n.created_at)}{n.acknowledged_at ? ` · 담당자 인수 ${date(n.acknowledged_at)}` : ' · 담당자 미확인'}</small>{n.last_error && <p className="ops-notification-error">{n.last_error}</p>}{retryId === n.id && <div className="ops-retry-form"><p>결과 미확인 알림은 이미 전송됐을 수 있습니다. 제공자 기록을 확인하고 재시도하세요.</p><input aria-label="알림 재시도 근거" placeholder="제공자 확인 결과 및 재시도 근거" value={reason} onChange={e => setReason(e.target.value)}/><button disabled={busy || reason.length < 3} onClick={() => void perform(async () => { await opsPost(`/notifications/${n.id}/retry`, { reason }); setRetryId(''); }, '알림 재전송을 예약했어요.')}>중복 가능성 확인 후 재시도</button></div>}</div><div><Badge value={n.status}/>{['failed', 'unknown'].includes(n.status) && <button className="ops-text-button" onClick={() => setRetryId(n.id)}>재시도 검토</button>}</div></article>)}</div> : <Empty title="전달 기록이 없습니다" text="새로운 사건의 알림 기록과 재시도 상태가 여기에 표시됩니다."/>}</section></>;
}
function Assets({ revision, actor, perform, busy }: { revision: number; actor: Operator; perform: Perform; busy: boolean }) {
  const { data, error } = useResource<{ items: Asset[]; points: Point[] }>('/assets', {}, revision, 10000);
  const [adding, setAdding] = useState(false), [name, setName] = useState(''), [address, setAddress] = useState(''), [port, setPort] = useState(443), [environment, setEnvironment] = useState('lab'), [protectedNetworks, setProtected] = useState(''), [pointAsset, setPointAsset] = useState(''), [pointName, setPointName] = useState(''), [token, setToken] = useState(''), [autoResponse, setAutoResponse] = useState(false), [assetReason, setAssetReason] = useState('');
  return <><Failure message={error}/><section className="ops-card"><div className="ops-section-head"><div><h2>자산과 서비스</h2><p>탐지 센서와 실제 정책 적용 지점을 구분해 등록합니다.</p></div>{actor.role === 'admin' && <button className="ops-secondary" onClick={() => setAdding(v => !v)}><Plus size={16}/>자산 등록</button>}</div>{adding && <form className="ops-policy-form" onSubmit={e => { e.preventDefault(); void perform(async () => { await opsPost('/assets', { name, address, service_port: port, environment, protected_cidrs: protectedNetworks.split(',').map(v => v.trim()).filter(Boolean), auto_response: autoResponse }); setAdding(false); }, '서비스 자산을 등록했어요.'); }}><label>서비스 이름<input aria-label="자산 이름" value={name} onChange={e => setName(e.target.value)} required maxLength={120}/></label><label>대상 IP<input aria-label="자산 IP" value={address} onChange={e => setAddress(e.target.value)} required/></label><label>서비스 포트<input aria-label="자산 포트" type="number" min={1} max={65535} value={port} onChange={e => setPort(Number(e.target.value))}/></label><label>환경<select value={environment} onChange={e => setEnvironment(e.target.value)}><option value="lab">소유한 실험실</option><option value="production">운영</option><option value="simulation">모의 훈련</option></select></label><label className="ops-full"><span className="term" title={termTitle(OPS_TERM.cidr)}>보호할 주소 범위(CIDR)</span><input aria-label="보호 CIDR" value={protectedNetworks} onChange={e => setProtected(e.target.value)} placeholder="절대 막으면 안 되는 주소: 관리 IP, DNS, 수집기 주소 · 쉼표로 구분"/></label><label className="ops-checkbox ops-full"><input type="checkbox" checked={autoResponse} onChange={e => setAutoResponse(e.target.checked)}/>자동 경로 등록 · 차단 안전 점검(Gate)이 저위험으로 판정하면 승인 없이 자동 차단해요</label><button className="ops-primary" disabled={busy}>자산 저장</button></form>}{data?.items.length ? <div className="ops-asset-grid">{data.items.map(a => <article key={a.id}><div><Shield size={22}/><span className={`ops-source ${a.environment}`}>{codeLabel(ENVIRONMENT, a.environment)}</span></div><h3>{a.name}</h3><code>{a.address}:{a.service_port}</code><p><span className="term" title={termTitle(OPS_TERM.cidr)}>보호 주소 범위(CIDR)</span> {a.protected_cidrs.length}개 · {a.criticality === 'critical' ? '중요 자산' : '일반 자산'} · {a.auto_response ? <span className="ops-auto-badge"><Bot size={12}/>자동 경로 등록</span> : '승인 전용 · 항상 다른 승인자가 검토'}</p>{actor.role === 'admin' && <div className="ops-switch-row"><input aria-label={`자동 경로 변경 근거 ${a.name}`} placeholder="자동 경로 변경 근거" value={assetReason} onChange={e => setAssetReason(e.target.value)} maxLength={2000}/><button className="ops-text-button" disabled={busy || assetReason.trim().length < 3} onClick={() => void perform(() => opsPost(`/assets/${a.id}/auto-response`, { enabled: !a.auto_response, reason: assetReason }), '이 자산의 자동 경로 설정을 바꿨어요.')}>{a.auto_response ? '자동 경로 해제' : '자동 경로 등록'}</button></div>}{data.points.filter(p => p.asset_id === a.id).map(p => <div className="ops-point" key={p.id}><span className={p.health.healthy ? 'ops-green' : 'ops-muted'}><Activity size={13}/>{p.name}</span><small>{codeLabel(POINT_MODE, p.mode)} · 최근 보고 {date(p.last_seen_at, '아직 없음')}</small><small>정상 요청 성공률 {pct(p.health.success_rate, '측정 안 됨')}</small></div>)}</article>)}</div> : <Empty title="등록된 자산이 없습니다" text="서비스 주소와 보호 대상을 등록하면 탐지와 대응을 같은 자산에 연결할 수 있습니다."/>}</section>{actor.role === 'admin' && <section className="ops-card"><div className="ops-section-head"><div><h3>대응 에이전트 등록</h3><p>등록 직후 발급되는 토큰은 한 번만 표시됩니다.</p></div><LockKeyhole size={20}/></div><form className="ops-policy-form" onSubmit={e => { e.preventDefault(); const a = data?.items.find(a => a.id === pointAsset); void perform(async () => { const result = await opsPost<Point & { token: string }>('/points', { asset_id: pointAsset, name: pointName, mode: a?.environment === 'simulation' ? 'lab' : 'nftables' }); setToken(result.token); }, '대응 지점을 등록했어요. 아래 토큰은 한 번만 보이니 에이전트에 안전하게 전달하세요.'); }}><label>연결할 자산<select aria-label="에이전트 자산" value={pointAsset} onChange={e => setPointAsset(e.target.value)} required><option value="">자산 선택</option>{data?.items.map(a => <option key={a.id} value={a.id}>{a.name} · {codeLabel(ENVIRONMENT, a.environment)}</option>)}</select></label><label>에이전트 이름<input aria-label="에이전트 이름" value={pointName} onChange={e => setPointName(e.target.value)} required/></label><button className="ops-primary" disabled={busy || !pointAsset}>에이전트 등록</button></form>{token && <div className="ops-token"><label>일회 표시 토큰<input aria-label="에이전트 일회 토큰" readOnly value={token}/></label><button onClick={() => setToken('')}>토큰 닫기</button></div>}</section>}</>;
}
function Models({ revision, actor, perform, busy }: { revision: number; actor: Operator; perform: Perform; busy: boolean }) {
  const { data, error } = useResource<ModelOverview>('/models', {}, revision);
  const [reason, setReason] = useState('');
  return <><Failure message={error}/><div className="ops-model-header"><Cpu size={30}/><div><span className="ops-eyebrow">AI 모델 운영</span><h2>운영 근거가 쌓일 때, 다음 단계로.</h2><p>{['offline', 'shadow', 'advisory', 'production'].map(stage => withOriginal(MODEL_STAGE[stage])).join(' → ')} · 승격은 자동 경로를 열지 않습니다 (자동 경로 {data ? (data.automatic_response_enabled ? '켜짐' : '꺼짐') : '확인 중'}).</p></div><span className="ops-source">{data ? `${engineLabel(data.runtime) || data.runtime} 운영` : '확인 중'}</span></div><div className="ops-model-signals"><span>네트워크 수집기(Collector) 관측 항목 버전 <b>{data?.collector_schema ?? '미관측'}</b></span><span>그림자 검증(Shadow) 상태 <b>{codeLabel(SHADOW_STATUS, data?.shadow_status, '확인 중')}</b></span><span title="실시간 관측 중 일정 비율만 골라 그림자 검증에 사용합니다">표본 추출 비율 <b>{data?.sample_modulus ? `1 / ${data.sample_modulus}` : data ? '미설정' : LOADING}</b></span></div>{data?.items.length ? data.items.map(m => <section className="ops-card ops-model" key={m.id}><div className="ops-section-head"><div><h3>{m.id}</h3><p>모델 해시 {m.artifact_hash.slice(0, 16)}…</p></div><Badge value={m.stage}/></div><div className="ops-facts"><div><span>실시간 관측</span><b>{m.statistics.samples.toLocaleString()}개</b></div><div><span>관측 항목·추론 오류율</span><b>{pct(m.statistics.failure_rate, '표본 없음')}</b></div><div><span title="가장 느린 5% 기준의 추론 시간">추론 시간(p95)</span><b>{m.statistics.p95_latency_ms == null ? '표본 없음' : `${m.statistics.p95_latency_ms.toFixed(1)} ms`}</b></div><div><span>규칙 판정과 불일치</span><b>{pct(m.statistics.disagreement_rate, '표본 없음')}</b></div></div><div className="ops-model-gates"><h4>승격 조건</h4>{m.gates.map(g => <div key={g.id} className={g.passed ? 'passed' : ''}>{g.passed ? <CheckCircle2 size={16}/> : <Clock3 size={16}/>}<span>{g.label}</span><b>{g.passed ? '통과' : '근거 필요'}</b></div>)}</div><div className="ops-warning">점수 분포 변화: {codeLabel(DRIFT_STATUS, m.statistics.drift_status)} · 운영 정답이 없는 관측을 오탐률이나 정확도로 환산하지 않습니다.</div>{actor.role === 'admin' && <div className="ops-model-controls"><input aria-label="모델 변경 근거" value={reason} onChange={e => setReason(e.target.value)} placeholder="모델 운영 단계 변경 근거"/>{[['offline', '그림자 검증(Shadow) 중단'], ['shadow', '그림자 검증(Shadow) 시작'], ['advisory', '참고(Advisory) 근거로 승격'], ['production', '실제 판정(Production)으로 승격']].map(([stage, text]) => <button key={stage} disabled={busy || reason.length < 3 || (['advisory', 'production'].includes(stage) && !m.promotion_ready)} onClick={() => void perform(() => opsPost(`/models/${m.id}/stage`, { stage, reason }), '모델 운영 단계를 바꿨어요.')}>{text}</button>)}</div>}</section>) : <section className="ops-card"><Empty title="등록된 Shadow 후보가 없습니다" text="관리자가 검증된 로컬 모델 묶음을 등록하면 실시간 관측과 승격 조건을 확인할 수 있습니다."/><a className="ops-secondary ops-center-link" href="#capture">기존 오프라인 평가 확인<ArrowRight size={15}/></a></section>}</>;
}
